// === Tab: mySketch ===
let w = 600, h = 600;
let s = 12;
let grid = 8;
let g = 6;

let pal = ['#4C6C77','#658094', '#658094', '#8592AE', '#AAA5C5', '#D2B7D6', '#F9CAE2', '#FFFEE5', '#4C6C77', '#658094'];

function mousePressed() {
	redraw();
}

function setup() {
  createCanvas(w, h);
	pixelDensity(2);
  noLoop();
  smooth();

  strokeCap(SQUARE);
}

function draw() {
  background(35, 65, 76);
  rectMode(CENTER);

  var nx, ny;
  var ss = s*5;

  shuffle(pal, true);
  noiseSeed(random(100));

  drawGrids();

	push();
  translate(ss, ss);


  for(let i = 1; i < grid; i++) {
    ny = i * ss;
    for(let j = 1; j < grid; j++) {
      nx = j * ss;

      push();
      translate(nx, ny);
      // fill(0,0,0,100);
      // rect(0,0,ss*0.9);
      // fill(0,0,90,100);
      drawPattern(nx, ny, ss*1);
      pop();
    }
  }

  pop();
  drawFrame();
}


// ------------------------------------- //
// ------------------------------------- //
// ------------------------------------- //

function drawPattern(x, y, d) {
  var type = random();

  if(type < 0.2) {
    drawPatternA(x, y, d);  
  } else if(type < 0.3) {
    drawPatternB(x, y, d);  
  } else if(type < 0.4) {
    drawPatternC(x, y, d);  
  } else if(type < 0.5) {
    drawPatternD(x, y, d);  
  } else if(type < 0.6) {
    drawPatternE(x, y, d);  
  } else if(type < 0.7) {
    drawPatternF(x, y, d);
  } else if(type < 0.8) {
    drawPatternG(x, y, d);
  } else if(type < 0.9) {
    drawPatternH(x, y, d);
  }else {
    drawPatternI(x, y, d);
  }

}

function drawPatternA(x, y, d) {
  noStroke();
  fill(getColor());
  rect(0, 0, d);
  push();
  if(random() < 0.2) {
    rotate(PI/2);  
  }
  fill(getColor());
  arc(-d/2, 0, d, d, -PI/2, PI/2);  
  fill(getColor());
  arc(d/2, 0, d, d, PI/2, -PI/2);  
  pop();
}

function drawPatternB(x, y, d) {
  noStroke();
  fill(getColor());
  rect(0, 0, d);
  push();
  var type = random();
  if(type < 0.2) {
    rotate(PI/2);  
  }
  else if(type < 0.4) {
    rotate(PI);  
  }
  else if(type < 0.6) {
    rotate(-PI/2);  
  }
  fill(getColor());
  triangle(0, 0, -d/2, -d/2, d/2, -d/2);
  fill(getColor());
  triangle(0, 0, d/2, -d/2, d/2, d/2);
  pop();

}

function drawPatternC(x, y, d) {
  noStroke();
  fill(getColor());
  rect(0, 0, d);

  var l = s*0.75;

  fill(getColor());
  circle(-d/4, -d/4, l);
  circle(0, -d/4, l);
  circle(d/4, -d/4, l);

  circle(-d/4, 0, l);
  circle(0, 0, l);
  circle(d/4, 0, l);

  circle(-d/4, d/4, l);
  circle(0, d/4, l);
  circle(d/4, d/4, l);
}

function drawPatternD(x, y, d) {
  noStroke();
  fill(getColor());
  rect(0, 0, d);

  push();
  var type = random();
  if(type < 0.2) {
    rotate(PI/2);  
  }
  else if(type < 0.4) {
    rotate(PI);  
  }
  else if(type < 0.6) {
    rotate(-PI/2);  
  }
  fill(getColor());
  arc(-d/2, -d/2, d*2-1, d*2-1, 0, PI/2, CHORD);
  arc(d/2, d/2, d*2-1, d*2-1, -PI, -PI/2, CHORD);
  pop();
}

function drawPatternE(x, y, d) {
  noStroke();
  fill(getColor());
  rect(0, 0, d);

  push();
  var type = random();
  if(type < 0.5) {
    rotate(PI);
  }
  fill(getColor());
  triangle(0, d/2, d/2, -d/2, -d/2, -d/2);

  if(random() < 0.6) {
    fill(getColor());
    circle(0,-s, s*1.5);    
  }
  pop();
}

function drawPatternF(x, y, d) {
  noStroke();
  fill(getColor());
  rect(0, 0, d);

  push();
  var type = random();
  if(type < 0.5) {
    rotate(PI/2);
  }
  stroke(getColor());
  strokeWeight(3);
  line(-d/4, -d/2, -d/4, d/2);
  line(0, -d/2, 0, d/2);
  line(d/4, -d/2, d/4, d/2);
  pop();
}

function drawPatternG(x, y, d) {
  noStroke();
  fill(getColor());
  rect(0, 0, d);

  push();
  var type = random();
  if(type < 0.5) {
    rotate(PI/2);
  }
  fill(getColor());
  arc(0, 0, d, d, 0, PI/2);
  arc(-d/2, -d/2, d, d, 0, PI/2);
  fill(getColor());
  arc(0, -d/2, d, d, 0, PI/2);
  arc(-d/2, 0, d, d, 0, PI/2);
  pop();
}

function drawPatternH(x, y, d) {
  noStroke();
  fill(getColor());
  rect(0, 0, d);

  push();
  var type = random();
  if(type < 0.5) {
    rotate(PI/2);
  }
  fill(getColor());
  triangle(0, 0, d/2, 0, d/2, -d/2);
  fill(getColor());
  triangle(0, 0, 0, -d/2, -d/2, -d/2);
  fill(getColor());
  triangle(0, 0, -d/2, 0, -d/2, d/2);
  fill(getColor());
  triangle(0, 0, 0, d/2, d/2, d/2);
  pop();
}

function drawPatternI(x, y, d) {
  noStroke();
  var c1 = getColor();
  var c2 = getColor();
  fill(c1);
  rect(0, 0, d);

  push();
  rotate(PI/4);

  fill(c2);
  rect(0, 0, d/1.5);
  fill(c1);
  rect(0, 0, d/1.8);
  fill(c2);
  rect(0, 0, d/2.4);
  fill(c1);
  rect(0, 0, d/3.2);
  fill(c2);
  rect(0, 0, d/5.4);
  pop();
}


function drawGrids() {
  stroke(0,0,10,100);
  strokeWeight(1.5);
  noFill();
  var tx = int(w / s);
  var ty = int(h / s);
  for(let i = 0; i < ty; i++) {
    cy = i * s;
    for(let j = 0; j < tx; j++) {
      cx = j * s;
      point(cx, cy);
    }
  } 
}

function drawFrame() {
  var s = 10;
  rectMode(CENTER);
  noStroke();
  fill(220);

  rect(s*2-1, h/2, s*4, h);
  rect(w-s*2+1, h/2, s*4, h);

  rect(w/2, s*2-1, w, s*4);
  rect(h/2, h-s*2+1, h, s*4);
}

function getColor() {
  var l = pal.length;
  var cc = random();
  shuffle(pal, true);
	var k = 20;

  if(cc < 1/l) {
    return pal[0];
  } else if (cc < 2/l-l/k) {
    return pal[1];
  } else if (cc < 3/l+l/k) {
    return pal[2];
  } else if (cc < 4/l-l/k) {
    return pal[3];
  } else if (cc < 5/l+l/k) {
    return pal[4];
  } else if (cc < 6/l-l/k) {
    return pal[5];
  } else if (cc < 7/l+l/k) {
    return pal[6];
  } else if (cc < 8/l-l/k) {
    return pal[7];
  } else if (cc < 9/l+l/k) {
    return pal[8];
  } else {
    return pal[9];
  }
}

